INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
-- Ja/Nein-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Ist ein Router notwendig, um Daten zwischen verschiedenen Subnetzen weiterzuleiten?', 2, '[{"text": "Ja", "correct": true, "because": "Router verbinden Subnetze"}, {"text": "Nein", "correct": false, "because": "Routing ist Hauptfunktion"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann ein Router auch als DHCP-Server fungieren?', 2, '[{"text": "Ja", "correct": true, "because": "Viele Router haben DHCP integriert"}, {"text": "Nein", "correct": false, "because": "DHCP ist oft verfügbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Muss ein Router immer eine WLAN-Funktion besitzen?', 2, '[{"text": "Nein", "correct": true, "because": "Kabelgebundene Router existieren"}, {"text": "Ja", "correct": false, "because": "WLAN ist optional"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist NAT (Network Address Translation) eine Standardfunktion moderner Router?', 2, '[{"text": "Ja", "correct": true, "because": "NAT ermöglicht Internetzugang"}, {"text": "No", "correct": false, "because": "NAT ist weit verbreitet"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann ein Router mehrere WAN-Verbindungen gleichzeitig unterstützen?', 2, '[{"text": "Ja", "correct": true, "because": "Dual-WAN-Router sind verfügbar"}, {"text": "Nein", "correct": false, "because": "Mehrere WANs möglich"}]'),

-- Single-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche Schicht des OSI-Modells ist primär für die Funktion eines Routers verantwortlich?', 2, '[{"text": "Schicht 3 (Netzwerkschicht)", "correct": true, "because": "Routing basiert auf IP"}, {"text": "Schicht 2 (Sicherungsschicht)", "correct": false, "because": "Für Switches"}, {"text": "Schicht 1 (Bitübertragungsschicht)", "correct": false, "because": "Physische Ebene"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Funktion eines Routers ermöglicht es, private IP-Adressen mit dem Internet zu verbinden?', 3, '[{"text": "NAT", "correct": true, "because": "Network Address Translation übersetzt Adressen"}, {"text": "VLAN", "correct": false, "because": "Für Netzwerktrennung"}, {"text": "QoS", "correct": false, "because": "Für Priorisierung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Port-Typ ist für die WAN-Verbindung eines Routers üblich?', 2, '[{"text": "RJ45", "correct": true, "because": "Standard für Ethernet"}, {"text": "SFP", "correct": false, "because": "Für Glasfaser, weniger üblich"}, {"text": "USB", "correct": false, "because": "Für Zusatzverbindungen"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher WLAN-Standard sollte ein Router für ein modernes Heimnetzwerk unterstützen?', 2, '[{"text": "802.11ax (Wi-Fi 6)", "correct": true, "because": "Hohe Geschwindigkeit und Effizienz"}, {"text": "802.11n", "correct": false, "because": "Älter, Wi-Fi 4"}, {"text": "802.11g", "correct": false, "because": "Veraltet"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Sicherheitsfunktion sollte ein Router standardmäßig bieten?', 2, '[{"text": "Firewall", "correct": true, "because": "Schützt vor unbefugtem Zugriff"}, {"text": "MAC-Filter", "correct": false, "because": "Optional"}, {"text": "VLAN", "correct": false, "because": "Für Trennung, nicht primär Sicherheit"}]'),

-- Multiple-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche Funktionen kann ein Router übernehmen?', 4, '[{"text": "Routing zwischen Netzwerken", "correct": true, "because": "Kernfunktion"}, {"text": "DHCP-Server", "correct": true, "because": "Vergibt IP-Adressen"}, {"text": "WLAN-Access-Point", "correct": true, "because": "Bei WLAN-Routern"}, {"text": "Paketanalyse", "correct": false, "because": "Für spezialisierte Tools"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Eigenschaften sind bei der Auswahl eines Routers für ein Unternehmen wichtig?', 3, '[{"text": "Hohe Bandbreitenkapazität", "correct": true, "because": "Für viele Nutzer"}, {"text": "VPN-Unterstützung", "correct": true, "because": "Für sicheren Zugriff"}, {"text": "QoS (Quality of Service)", "correct": true, "because": "Priorisiert Datenverkehr"}, {"text": "Bluetooth", "correct": false, "because": "Nicht netzwerkrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Ports sind typischerweise an einem Router vorhanden?', 4, '[{"text": "WAN-Port", "correct": true, "because": "Für Internetverbindung"}, {"text": "LAN-Ports", "correct": true, "because": "Für lokale Geräte"}, {"text": "USB-Port", "correct": true, "because": "Für Zusatzfunktionen"}, {"text": "HDMI-Port", "correct": false, "because": "Für Video, nicht Router"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet ein Router mit Wi-Fi 6 im Vergleich zu Wi-Fi 5?', 3, '[{"text": "Höhere Geschwindigkeit", "correct": true, "because": "Bis zu 9,6 Gbit/s"}, {"text": "Bessere Effizienz bei hoher Dichte", "correct": true, "because": "OFDMA und MU-MIMO"}, {"text": "Geringere Reichweite", "correct": false, "because": "Reichweite ähnlich"}, {"text": "Unterstützung für mehr Geräte", "correct": true, "because": "Effizientere Nutzung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Kriterien sollten bei der Auswahl eines Routers für ein kleines Büro berücksichtigt werden?', 3, '[{"text": "Anzahl der LAN-Ports", "correct": true, "because": "Für Geräteanzahl"}, {"text": "WLAN-Reichweite", "correct": true, "because": "Für Abdeckung"}, {"text": "Firewall-Funktion", "correct": true, "because": "Für Sicherheit"}, {"text": "Farbe des Gehäuses", "correct": false, "because": "Irrelevant"}]'),

-- Richtig/Falsch-Kombinationsfragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen richtig? a) Ein Router arbeitet primär auf Schicht 3 des OSI-Modells. b) Ein Router ist für die Verbindung innerhalb eines LANs ausreichend ohne Switch.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Schicht 3 ja, Switch oft nötig"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) NAT ist essenziell für den Internetzugang eines privaten Netzwerks. b) Ein Router mit Wi-Fi 6 unterstützt nur 5-GHz-Bänder.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "NAT ja, Wi-Fi 6 auch 2,4 GHz"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Ein Router kann mehrere WAN-Verbindungen für Redundanz nutzen. b) Ein Router ohne DHCP kann keine IP-Adressen vergeben.', 3, '[{"text": "Beides stimmt", "correct": true, "because": "Dual-WAN ja, DHCP nötig für Vergabe"}, {"text": "Nur a) stimmt", "correct": false, "because": "b) ist auch richtig"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist auch richtig"}, {"text": "Beides falsch", "correct": false, "because": "Beides ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen korrekt? a) Ein Router mit Firewall schützt vor unbefugtem Zugriff. b) Ein Router muss immer WLAN unterstützen.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Firewall ja, WLAN optional"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) QoS in einem Router kann Datenverkehr priorisieren. b) Ein Router ohne NAT kann keine privaten Netzwerke mit dem Internet verbinden.', 3, '[{"text": "Beides stimmt", "correct": true, "because": "QoS ja, NAT nötig für private IPs"}, {"text": "Nur a) stimmt", "correct": false, "because": "b) ist auch richtig"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist auch richtig"}, {"text": "Beides falsch", "correct": false, "because": "Beides ist richtig"}]');

